arguments.content:
/* Replicates GParted 1.8.0 FAT32 grow path:
 *   GParted_Core::resize_plain()            -> resize_move_partition() then maximize_filesystem()
 *   GParted_Core::resize_move_partition_implement() -> ped_disk_set_partition_geom + commit
 *   GParted_Core::maximize_filesystem()     -> resize_filesystem_implement(partition, partition)
 *   GParted_Core::resize_move_filesystem_using_libparted()
 *       -> ped_file_system_open(old geom); ped_file_system_resize(fs, new geom); commit
 *
 * usage: lpgrow <disk-device> <partition-number> <old-len-sectors> <new-len-sectors>
 */
#include <parted/parted.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int ex_handler(PedExContext *ctx, PedExProblem *prob)
{
	fprintf(stderr, "[ped exception] %s: %s\n",
	        prob->type == PED_EXCEPTION_ERROR ? "ERROR" :
	        prob->type == PED_EXCEPTION_WARNING ? "WARNING" : "INFO",
	        prob->message);
	return PED_EXCEPTION_UNHANDLED;  /* let libparted return failure */
}

int main(int argc, char **argv)
{
	if (argc != 5) { fprintf(stderr, "usage: %s dev partnum old_len new_len\n", argv[0]); return 2; }
	const char *devpath = argv[1];
	int partnum = atoi(argv[2]);
	Sector old_len = atoll(argv[3]);
	Sector new_len = atoll(argv[4]);

	ped_exception_set_handler(ex_handler);

	PedDevice *dev = ped_device_get(devpath);
	if (!dev) { fprintf(stderr, "ped_device_get failed\n"); return 1; }
	printf("device %s sector_size=%d\n", dev->path, dev->sector_size);

	PedDisk *disk = ped_disk_new(dev);
	if (!disk) { fprintf(stderr, "ped_disk_new failed\n"); return 1; }

	PedPartition *part = ped_disk_get_partition(disk, partnum);
	if (!part) { fprintf(stderr, "ped_disk_get_partition failed\n"); return 1; }
	Sector start = part->geom.start;
	printf("partition %d: start=%lld len=%lld (expected len %lld)\n",
	       partnum, (long long)start, (long long)part->geom.length, (long long)old_len);

	/* ---- step 1: grow the partition boundary (resize_move_partition) ---- */
	PedGeometry *new_geom = ped_geometry_new(dev, start, new_len);
	PedConstraint *c = ped_constraint_exact(new_geom);
	int ok = ped_disk_set_partition_geom(disk, part, c, new_geom->start, new_geom->end);
	printf("ped_disk_set_partition_geom = %d; part len now %lld\n", ok, (long long)part->geom.length);
	ped_constraint_destroy(c);
	if (ok) {
		ok = ped_disk_commit(disk);
		printf("ped_disk_commit = %d\n", ok);
	}

	/* ---- step 2: grow the filesystem (resize_move_filesystem_using_libparted) ---- */
	PedGeometry *old_geom = ped_geometry_new(dev, start, old_len);
	PedFileSystem *fs = ped_file_system_open(old_geom);
