*576|/*  For resize operations: determine if the file system must be FAT16 or FAT32,
*577| *  or either.  If the new file system must be FAT32, then query for
*578| *  confirmation.  If either file system can be used, query for which one.
*579| */
*580|static int
*581|get_fat_type (PedFileSystem* fs, const PedGeometry* new_geom,
*582|	      FatType* out_fat_type)
*583|{
*584|	FatSpecific*		fs_info = FAT_SPECIFIC (fs);
*585|	PedSector		fat16_cluster_sectors;
*586|	PedSector		fat32_cluster_sectors;
*587|	FatCluster		dummy_cluster_count;
*588|	PedSector		dummy_fat_sectors;
*589|	int			fat16_ok;
*590|	int			fat32_ok;
 591|
*592|	fat16_ok = fat_calc_resize_sizes (
*593|				    new_geom,
*594|				    fs_info->cluster_sectors,
*595|				    FAT_TYPE_FAT16,
*596|				    fs_info->root_dir_sector_count,
*597|				    fs_info->cluster_sectors,
*598|				    &fat16_cluster_sectors,
*599|				    &dummy_cluster_count,
*600|				    &dummy_fat_sectors);
 601|
*602|	fat32_ok = fat_calc_resize_sizes (
*603|				    new_geom,
*604|				    fs_info->cluster_sectors,
*605|				    FAT_TYPE_FAT32,
*606|				    fs_info->root_dir_sector_count,
*607|				    fs_info->cluster_sectors,
*608|				    &fat32_cluster_sectors,
*609|				    &dummy_cluster_count,
*610|				    &dummy_fat_sectors);
 611|
*612|	return ask_type (fs, fat16_ok, fat32_ok, out_fat_type);
*613|}
 614|
*615|/*  Creates the PedFileSystem struct for the new resized file system, and
*616|    sticks it in a FatOpContext.  At the end of the process, the original
*617|    (ctx->old_fs) is destroyed, and replaced with the new one (ctx->new_fs).
*618| */
*619|static FatOpContext*
*620|create_resize_context (PedFileSystem* fs, const PedGeometry* new_geom)
*621|{
*622|	FatSpecific*	fs_info = FAT_SPECIFIC (fs);
*623|	FatSpecific*	new_fs_info;
*624|	PedFileSystem*	new_fs;
*625|	PedSector	new_cluster_sectors;
*626|	FatCluster	new_cluster_count;
*627|	PedSector	new_fat_sectors;
*628|	FatType		new_fat_type;
*629|	PedSector	root_dir_sector_count;
*630|	FatOpContext*	context;
 631|
*632|	/* hypothetical number of root dir sectors, if we end up using
*633|	 * FAT16
*634|	 */
*635|	if (fs_info->root_dir_sector_count)
*636|		root_dir_sector_count = fs_info->root_dir_sector_count;
*637|	else
*638|		root_dir_sector_count = FAT_ROOT_DIR_ENTRY_COUNT
*639|						* sizeof (FatDirEntry) / 512;
 640|
*641|	if (!get_fat_type (fs, new_geom, &new_fat_type))
*642|		return 0;
 643|
*644|	fat_calc_resize_sizes (new_geom, fs_info->cluster_sectors, new_fat_type,
*645|		root_dir_sector_count, fs_info->cluster_sectors,
*646|		&new_cluster_sectors, &new_cluster_count, &new_fat_sectors);
 647|
*648|	if (!fat_check_resize_geometry (fs, new_geom, new_cluster_sectors,
*649|				        new_cluster_count))
*650|		goto error;
 651|
*652|	new_fs = fat_alloc (new_geom);
*653|	if (!new_fs)
*654|		goto error;
 655|
*656|	new_fs_info = FAT_SPECIFIC (new_fs);
*657|	if (!new_fs_info)
*658|		goto error_free_new_fs;
 659|
*660|/* preserve boot code, etc. */
*661|	new_fs_info->boot_sector = ped_malloc (new_geom->dev->sector_size);
*662|	memcpy (new_fs_info->boot_sector, fs_info->boot_sector,
*663|		new_geom->dev->sector_size);
*664|	new_fs_info->info_sector = NULL;
*665|	if (fs_info->fat_type == FAT_TYPE_FAT32)
*666|	{
*667|		PED_ASSERT (fs_info->info_sector != NULL);
*668|		new_fs_info->info_sector =
*669|			ped_malloc (new_geom->dev->sector_size);
*670|		memcpy (new_fs_info->info_sector, fs_info->info_sector,
*671|			new_geom->dev->sector_size);
*672|	}
 673|
*674|	new_fs_info->logical_sector_size = fs_info->logical_sector_size;
*675|	new_fs_info->sector_count = new_geom->length;
 676|
*677|	new_fs_info->sectors_per_track = fs_info->sectors_per_track;
*678|	new_fs_info->heads = fs_info->heads;
 679|
*680|	new_fs_info->cluster_size = new_cluster_sectors * 512;
