*323|	PedSector	raw_old_meta_data_end;
*324|	PedSector	new_meta_data_size;
*325|	PedSector	min_new_meta_data_end;
*326|	PedSector	new_data_size;
*327|	PedSector	new_clusters_size;
*328|	PedSector	align;
